'use strict';

// MODULES //

var tape = require( 'tape' );
var isDataSet = require( '@stdlib/plot/vega/base/assert/is-dataset' );
var objarray2tidy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof objarray2tidy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a data set', function test( t ) {
	var out = objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'data', { 'a': 'x', 'b': 'y' } );
	t.strictEqual( isDataSet( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having a specified name', function test( t ) {
	var out = objarray2tidy( [ { 'a': 1, 'b': 2 } ], 'beep', { 'a': 'x', 'b': 'y' } );
	t.strictEqual( out.name, 'beep', 'returns expected value' );
	t.end();
});

tape( 'the function converts an array of objects to a "tidy" data set', function test( t ) {
	var expected;
	var actual;

	actual = objarray2tidy( [ { 'a': 1, 'b': 2 }, { 'a': 3, 'b': 4 } ], 'data' ).toJSON().values;
	expected = [
		{
			'a': 1,
			'b': 2
		},
		{
			'a': 3,
			'b': 4
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying a mapping object', function test( t ) {
	var expected;
	var actual;
	var i;

	actual = objarray2tidy( [ { 'a': 1, 'b': 2 }, { 'a': 3, 'b': 4 } ], 'data', { 'a': 'x', 'b': 'y' } ).toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'x': 1,
			'y': 2
		},
		{
			'x': 3,
			'y': 4
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having no values if provided an empty array', function test( t ) {
	var expected;
	var actual;

	actual = objarray2tidy( [], 'data', { 'a': 'x', 'b': 'y' } ).toJSON().values;
	expected = [];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
